  "inlineSchema": "// Prisma schema for Campus Complaint and Feedback Portal\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  STUDENT\n  COORDINATOR\n  DEPARTMENT\n  ADMIN\n}\n\nenum ComplaintStatus {\n  PENDING_VERIFICATION\n  VERIFIED\n  REJECTED\n  ASSIGNED\n  IN_PROGRESS\n  RESOLVED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nmodel User {\n  id            String   @id @default(uuid())\n  name          String\n  email         String   @unique\n  password      String\n  role          Role     @default(STUDENT)\n  contactNumber String?\n  classId       String?\n  departmentId  String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  // Student belongs to a Class\n  class Class? @relation(\"ClassStudents\", fields: [classId], references: [id])\n\n  // Coordinator manages Classes (one-to-many: a coordinator can manage multiple classes)\n  managedClasses Class[] @relation(\"ClassCoordinator\")\n\n  // Department user belongs to a Department\n  department Department? @relation(\"DepartmentUsers\", fields: [departmentId], references: [id])\n\n  // Complaints created by this student\n  complaints Complaint[]\n\n  // Feedback submitted by this student\n  feedbacks Feedback[]\n\n  // Complaint updates created by this user\n  complaintUpdates ComplaintUpdate[]\n\n  // Audit logs where this user was the actor\n  auditLogsAsActor AuditLog[] @relation(\"AuditActor\")\n\n  // Audit logs where this user was the target\n  auditLogsAsTarget AuditLog[] @relation(\"AuditTarget\")\n\n  @@index([classId])\n  @@index([departmentId])\n}\n\nmodel Class {\n  id            String   @id @default(uuid())\n  className     String   @unique\n  department    String?\n  coordinatorId String?\n  createdAt     DateTime @default(now())\n\n  // Coordinator assigned to this class\n  coordinator User? @relation(\"ClassCoordinator\", fields: [coordinatorId], references: [id])\n\n  // Students in this class\n  students User[] @relation(\"ClassStudents\")\n\n  // Complaints belonging to this class\n  complaints Complaint[]\n\n  @@index([coordinatorId])\n}\n\nmodel Department {\n  id        String   @id @default(uuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n\n  // Complaints assigned to this department\n  complaints Complaint[]\n\n  // Users belonging to this department\n  users User[] @relation(\"DepartmentUsers\")\n}\n\nmodel Complaint {\n  id                String          @id @default(uuid())\n  studentId         String\n  classId           String\n  title             String\n  category          String\n  description       String\n  location          String?\n  attachmentUrl     String?\n  priority          Priority        @default(MEDIUM)\n  status            ComplaintStatus @default(PENDING_VERIFICATION)\n  coordinatorRemark String?\n  rejectionReason   String?\n  departmentId      String?\n  adminRemark       String?\n  assignedAt        DateTime?\n  createdAt         DateTime        @default(now())\n  updatedAt         DateTime        @updatedAt\n  resolvedAt        DateTime?\n\n  // Relations\n  student    User        @relation(fields: [studentId], references: [id])\n  class      Class       @relation(fields: [classId], references: [id])\n  department Department? @relation(fields: [departmentId], references: [id])\n\n  // Feedback for this complaint (one-to-one)\n  feedback Feedback?\n\n  // Progress history\n  updates ComplaintUpdate[]\n\n  @@index([studentId])\n  @@index([classId])\n  @@index([departmentId])\n  @@index([status])\n}\n\nmodel Feedback {\n  id          String   @id @default(uuid())\n  complaintId String   @unique\n  studentId   String\n  rating      Int\n  comment     String?\n  createdAt   DateTime @default(now())\n\n  // Relations\n  complaint Complaint @relation(fields: [complaintId], references: [id])\n  student   User      @relation(fields: [studentId], references: [id])\n\n  @@index([studentId])\n}\n\nmodel ComplaintUpdate {\n  id          String          @id @default(uuid())\n  complaintId String\n  userId      String?\n  status      ComplaintStatus\n  message     String\n  createdAt   DateTime        @default(now())\n\n  // Relations\n  complaint Complaint @relation(fields: [complaintId], references: [id])\n  user      User?     @relation(fields: [userId], references: [id])\n\n  @@index([complaintId])\n  @@index([userId])\n}\n\nmodel AuditLog {\n  id           String   @id @default(uuid())\n  actorUserId  String\n  targetUserId String?\n  action       String\n  oldRole      String?\n  newRole      String?\n  details      String?\n  createdAt    DateTime @default(now())\n\n  // Relations\n  actor  User  @relation(\"AuditActor\", fields: [actorUserId], references: [id])\n  target User? @relation(\"AuditTarget\", fields: [targetUserId], references: [id])\n\n  @@index([actorUserId])\n  @@index([targetUserId])\n}\n",
